"""Counts tonight's pre-orders. It has a bug. Do not edit this file.

Usage: python night.py ORDERS_FILE
"""
import json
import sys


def main():
    if len(sys.argv) != 2:
        print("Usage: python night.py ORDERS_FILE")
        return 2
    with open(sys.argv[1], encoding="utf-8") as f:
        orders = json.load(f)
    count = sum(order["count"] for order in orders)
    print(f"Tonight we have {count} pre-orders.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
